```c
#include <stdio.h>

int main(void) {
    char p[105], a[105];
    if (scanf("%s", p) != 1) return 0;
    if (scanf("%s", a) != 1) return 0;

    int count[26] = {0};

    for (int i = 0; p[i] != '\0'; i++) {
        count[p[i] - 'a']++;
    }

    for (int i = 0; a[i] != '\0'; i++) {
        if (a[i] != '*') {
            int idx = a[i] - 'a';
            count[idx]--;
            if (count[idx] < 0) {
                printf("N\n");
                return 0;
            }
        }
    }

    printf("S\n");
    return 0;
}
```

